<?php require_once __DIR__.'/includes/config.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$pdo->prepare('SELECT * FROM users WHERE email=?');$s->execute([trim($_POST['email']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['user_name']=$u['full_name'];header('Location: dashboard.php');exit;}$error='Email or password is incorrect.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Applicant Login | Ladle Loan</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="form-wrap"><form class="form-card" method="post"><a href="index.php">← Ladle Loan</a><h1>Applicant login</h1><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn">Login</button><p>New here? <a href="register.php">Create account</a></p></form></div></body></html>